(3596792, 504595, 43031, '<td valign="top">pretty subtle, I wonder how many missed it.</td>', 'pretty subtle, I wonder how many missed it.', '2007-04-30 18:04:44.000000', NULL, 1),
(3596793, 504783, 3746, '<td valign="top">I like the continunity carried through each frame with the branches then the roses. nice layout, pretty pictures. works well for me. 8</td>', 'I like the continunity carried through each frame with the branches then the roses. nice layout, pretty pictures. works well for me. 8', '2007-04-30 18:05:00.000000', NULL, 1),
