(3604823, 504261, 66597, '<td valign="top">One of the best in the challenge IMO. Love the shapes and continuity.</td>', 'One of the best in the challenge IMO. Love the shapes and continuity.', '2007-05-02 09:35:40.000000', NULL, 1),
(3604824, 504938, 66597, '<td valign="top">Nicely done! Colors are vivid and the lines continueous.</td>', 'Nicely done! Colors are vivid and the lines continueous.', '2007-05-02 09:35:43.000000', NULL, 1),
(3604825, 505102, 66597, '<td valign="top">Yikes - this looks very real. I hope it isn''t! (I understand domestic abuse is all too real, but I hope this photo series was staged.) Well-taken, and very captivating.</td>', 'Yikes - this looks very real. I hope it isn''t! (I understand domestic abuse is all too real, but I hope this photo series was staged.) Well-taken, and very captivating.', '2007-05-02 09:35:46.000000', NULL, 1),
(3604861, 503333, 18219, '<td valign="top">A nice strong image with bright bold colors, it just appears to be let down by the tulips being out of focus?</td>', 'A nice strong image with bright bold colors, it just appears to be let down by the tulips being out of focus?', '2007-05-02 09:44:58.000000', NULL, 1),
(3604889, 504594, 44741, '<td valign="top">Why black and white? This would have looked nicer in color, I think.</td>', 'Why black and white? This would have looked nicer in color, I think.', '2007-05-02 09:51:29.000000', NULL, 1),
